//! Scenario test: two merchants, fifty orders (44 escrow on-chain; the 6
//! express orders are classic claimable balances and are not in this test).
//!
//! `test_seed.rs` is generated by `refundwin seed` from data/seed/. It holds the
//! orders, the complete call schedule the offline simulator produced (buyer,
//! merchant and arbiter actions from events.jsonl, plus every keeper call,
//! including the 26 h keeper outage, the late dispute, the duplicate id and the
//! failed refund retries while a trustline was missing) and the final state the
//! TypeScript model reached. This test replays the schedule on the real
//! contract, checks every call's outcome, checks the per-token invariant after
//! every call, and then compares final states, amounts and balances.
extern crate std;

use super::*;
use crate::test_seed::*;
use soroban_sdk::testutils::{Address as _, IssuerFlags, Ledger as _};
use soroban_sdk::{token, Bytes};
use std::collections::BTreeMap;
use std::format;
use std::string::String;
use std::vec::Vec as StdVec;

struct World {
    env: Env,
    id: Address,
    tokens: StdVec<Address>,
    arbiter: Address,
    fee_to: Address,
    merchants: StdVec<Address>,
    payouts: StdVec<Address>,
    buyers: StdVec<Address>,
    extra: StdVec<Address>,
}

impl World {
    fn c(&self) -> RefundEscrowClient<'_> {
        RefundEscrowClient::new(&self.env, &self.id)
    }
    fn who(&self, w: Who) -> Option<Address> {
        match w {
            Who::Nobody => None,
            Who::Buyer(i) => Some(self.buyers[i].clone()),
            Who::Extra(i) => Some(self.extra[i].clone()),
        }
    }
    fn order_of(&self, n: u32) -> &'static SeedOrder {
        ORDERS.iter().find(|o| o.n == n).expect("order in seed")
    }
    fn oid(&self, bytes: &[u8; 32]) -> BytesN<32> {
        BytesN::from_array(&self.env, bytes)
    }
    fn bal(&self, t: usize, who: &Address) -> i128 {
        token::Client::new(&self.env, &self.tokens[t]).balance(who)
    }
    fn assert_token_invariants(&self) {
        let mut due = [0i128; 3];
        for o in ORDERS {
            if let Some(s) = self.c().order(&self.oid(&o.id)) {
                due[o.token] += s.held + s.refund_owed;
            }
        }
        for (t, tok) in self.tokens.iter().enumerate() {
            assert_eq!(self.bal(t, &self.id), due[t] + self.c().fees(tok), "token invariant for {}", TOKENS[t]);
        }
    }
}

fn setup() -> World {
    let env = Env::default();
    env.mock_all_auths();
    env.cost_estimate().budget().reset_unlimited();
    env.ledger().set_timestamp(T0);
    let g = |e: &Env| Address::generate(e);
    let admin = g(&env);
    let arbiter = g(&env);
    let fee_to = g(&env);
    let id = env.register(
        RefundEscrow,
        (admin.clone(), arbiter.clone(), fee_to.clone(), ARBITER_TIMEOUT, MIN_WINDOW, MAX_WINDOW),
    );
    let issuer = g(&env);
    let tokens: StdVec<Address> = TOKENS
        .iter()
        .map(|_| {
            let sac = env.register_stellar_asset_contract_v2(issuer.clone());
            sac.issuer().set_flag(IssuerFlags::RevocableFlag);
            sac.address()
        })
        .collect();
    let merchants: StdVec<Address> = MERCHANTS.iter().map(|_| g(&env)).collect();
    let payouts: StdVec<Address> = MERCHANTS.iter().map(|_| g(&env)).collect();
    let buyers: StdVec<Address> = (0..N_BUYERS).map(|_| g(&env)).collect();
    let extra: StdVec<Address> = (0..N_EXTRA).map(|_| g(&env)).collect();
    let w = World { env, id, tokens, arbiter, fee_to, merchants, payouts, buyers, extra };
    for t in &w.tokens {
        w.c().set_token(t, &true);
    }
    for (i, m) in MERCHANTS.iter().enumerate() {
        w.c().add_merchant(&w.merchants[i], &w.payouts[i], &m.fee_bps, &m.window);
    }
    // Each buyer holds exactly what it pays, so its final balance is exactly
    // what was refunded to it.
    let mut need: BTreeMap<(usize, usize), i128> = BTreeMap::new();
    for o in ORDERS {
        *need.entry((o.buyer, o.token)).or_default() += o.amount;
    }
    for ((b, t), amt) in need {
        token::StellarAssetClient::new(&w.env, &w.tokens[t]).mint(&w.buyers[b], &amt);
    }
    w
}

fn outcome<T, E>(r: Result<T, Result<Error, E>>) -> (String, Option<T>) {
    match r {
        Ok(v) => (String::from("ok"), Some(v)),
        Err(Ok(e)) => (format!("{:?}", e), None),
        Err(Err(_)) => (String::from("HostError"), None),
    }
}

fn ok_val<T, C>(r: Result<Result<T, C>, Result<Error, soroban_sdk::InvokeError>>) -> (String, Option<T>) {
    let (s, v) = outcome(r);
    (s, v.and_then(|x| x.ok()))
}

#[test]
fn scenario_two_merchants_fifty_orders() {
    let w = setup();
    let c = w.c();
    let mut kinds: BTreeMap<&str, u32> = BTreeMap::new();
    for (i, call) in CALLS.iter().enumerate() {
        w.env.ledger().set_timestamp(call.at);
        *kinds.entry(call.kind).or_default() += 1;
        let (got, ret): (String, i128) = match call.kind {
            "pay" | "pay_dup" => {
                let o = w.order_of(call.order);
                let (id, amount, refund_to, window) = if call.kind == "pay" {
                    (w.oid(&o.id), o.amount, w.who(o.refund_to), o.window)
                } else {
                    (w.oid(&call.id), call.amount, None, None)
                };
                assert_eq!(call.amount, amount);
                let (s, _) = ok_val(c.try_pay(
                    &w.buyers[o.buyer],
                    &w.merchants[o.merchant],
                    &id,
                    &w.tokens[o.token],
                    &amount,
                    &refund_to,
                    &window,
                    &w.oid(&o.memo),
                ));
                (s, 0)
            }
            "refund" => {
                let o = w.order_of(call.order);
                (ok_val(c.try_refund(&w.oid(&o.id), &call.amount)).0, 0)
            }
            "deauth" | "reauth" => {
                let who = w.who(call.who).unwrap();
                token::StellarAssetClient::new(&w.env, &w.tokens[call.token]).set_authorized(&who, &(call.kind == "reauth"));
                (String::from("ok"), 0)
            }
            "dispute" => {
                let o = w.order_of(call.order);
                (ok_val(c.try_dispute(&w.oid(&o.id), &call.reason, &w.oid(&call.hash))).0, 0)
            }
            "respond" => {
                let o = w.order_of(call.order);
                (ok_val(c.try_respond(&w.oid(&o.id), &w.oid(&call.hash))).0, 0)
            }
            "withdraw_dispute" => {
                let o = w.order_of(call.order);
                (ok_val(c.try_withdraw_dispute(&w.oid(&o.id))).0, 0)
            }
            "resolve" => {
                let o = w.order_of(call.order);
                let r = ok_val(c.try_resolve(&w.oid(&o.id), &call.amount, &w.oid(&call.hash))).0;
                // Only the snapshot arbiter signed.
                if r == "ok" {
                    assert_eq!(w.env.auths()[0].0, w.arbiter);
                }
                (r, 0)
            }
            "release_many" => {
                let mut ids = soroban_sdk::Vec::new(&w.env);
                for n in call.ids {
                    ids.push_back(w.oid(&w.order_of(*n).id));
                }
                let (s, v) = ok_val(c.try_release_many(&ids));
                (s, v.unwrap_or(0) as i128)
            }
            "timeout" => {
                let o = w.order_of(call.order);
                (ok_val(c.try_timeout_refund(&w.oid(&o.id))).0, 0)
            }
            "settle" => {
                let o = w.order_of(call.order);
                let (s, v) = ok_val(c.try_settle_refund(&w.oid(&o.id)));
                (s, v.unwrap_or(0))
            }
            "withdraw_fees" => {
                let (s, v) = ok_val(c.try_withdraw_fees(&w.tokens[call.token]));
                (s, v.unwrap_or(0))
            }
            other => panic!("unknown call kind {other}"),
        };
        assert_eq!(got, call.expect, "call #{i} {} order {} at {}", call.kind, call.order, call.at);
        assert_eq!(ret, call.ret, "call #{i} {} return value", call.kind);
        w.assert_token_invariants();
    }

    // Final state of every order equals the TypeScript model's.
    let mut states: BTreeMap<String, u32> = BTreeMap::new();
    let mut late = 0u32;
    for o in ORDERS {
        let s = c.order(&w.oid(&o.id)).unwrap();
        let st = format!("{:?}", s.state);
        assert_eq!(st, o.state, "order {} ({}) state", o.n, o.tag);
        assert_eq!(
            (s.held, s.refunded, s.refund_owed, s.released, s.fee),
            (o.held, o.refunded, o.refund_owed, o.released, o.fee),
            "order {} ({}) amounts",
            o.n,
            o.tag
        );
        assert_eq!((s.release_at, s.closed_at), (o.release_at, o.closed_at), "order {} times", o.n);
        assert_eq!(s.amount, s.held + s.refunded + s.released + s.fee);
        assert_eq!(s.payout, w.payouts[o.merchant]);
        let expected_refund_to = w.who(o.refund_to).unwrap_or(w.buyers[o.buyer].clone());
        assert_eq!(s.refund_to, expected_refund_to);
        *states.entry(st.clone()).or_default() += 1;
        if st == "Released" && s.closed_at - s.release_at > 600 {
            late += 1;
        }
    }
    let want: BTreeMap<String, u32> = EXPECTED_STATES.iter().map(|(k, v)| (String::from(*k), *v)).collect();
    assert_eq!(states, want);
    assert_eq!(late, EXPECTED_LATE_RELEASES, "releases delayed by the keeper outage");

    // Balances per token: payouts, refund addresses, fee_to, and an empty contract.
    for t in TOTALS {
        for (m, payout) in w.payouts.iter().enumerate() {
            assert_eq!(w.bal(t.token, payout), t.payout[m], "{} payout of merchant {}", TOKENS[t.token], m);
        }
        let mut refunded = 0i128;
        for a in w.buyers.iter().chain(w.extra.iter()) {
            refunded += w.bal(t.token, a);
        }
        assert_eq!(refunded, t.refunded, "{} refunds landed at refund_to addresses", TOKENS[t.token]);
        assert_eq!(w.bal(t.token, &w.fee_to), t.fees, "{} fees", TOKENS[t.token]);
        assert_eq!(w.bal(t.token, &w.id), 0, "{} contract balance after withdraw_fees", TOKENS[t.token]);
        assert_eq!(t.payout[0] + t.payout[1] + t.refunded + t.fees, t.paid, "{} conservation", TOKENS[t.token]);
        // Nobody else gained anything.
        assert_eq!(w.bal(t.token, &w.arbiter), 0);
        for m in &w.merchants {
            assert_eq!(w.bal(t.token, m), 0);
        }
    }
    // Refunds only ever reached the address bound at checkout.
    for o in ORDERS {
        if let Who::Extra(i) = o.refund_to {
            assert_eq!(w.bal(o.token, &w.extra[i]), o.refunded - o.refund_owed);
            assert_eq!(w.bal(o.token, &w.buyers[o.buyer]), 0, "the buyer of a separate-refund_to order got nothing");
        }
    }
    std::println!("scenario: {} calls replayed {:?}; final states {:?}; late releases {}", CALLS.len(), kinds, states, late);
}

// ---------------------------------------------------------------------------
// Order-id normalisation vectors shared with app/test/orderid.test.ts
// ---------------------------------------------------------------------------

fn normalise(r: &str) -> String {
    r.trim()
        .chars()
        .filter(|c| !c.is_whitespace() && *c != '#' && *c != '-')
        .flat_map(|c| c.to_uppercase())
        .collect()
}

#[test]
fn order_id_vectors_match_typescript() {
    let env = Env::default();
    for (merchant, raw, norm, id) in ORDER_ID_VECTORS {
        assert_eq!(normalise(raw), *norm, "normalise({raw:?})");
        let pre = format!("{merchant}:{norm}");
        let h = env.crypto().sha256(&Bytes::from_slice(&env, pre.as_bytes()));
        assert_eq!(h.to_array(), *id, "order id for {raw:?}");
    }
    // "ord 1044", "ORD-1044" and "#ORD1044" are one order.
    assert_eq!(ORDER_ID_VECTORS[0].3, ORDER_ID_VECTORS[1].3);
    assert_eq!(ORDER_ID_VECTORS[0].3, ORDER_ID_VECTORS[2].3);
}
